#pragma once

#include "recognizer/recognizer_service.h"

#include <functional>
#include <optional>
#include <string>

#if SU_HAS_SLINT
#include <slint/slint.h>
#endif

namespace su::app {

// Overlay data derived from a preview frame: the detected face box, the
// liveness score, and a human-readable status line. Pushed alongside the
// preview image so the UI can draw the box and stats in one update.
struct PreviewOverlay {
    std::optional<su::recognizer::FaceBox> face_box;
    float liveness_score = 0.0F;
    std::string status_text;
};

#if SU_HAS_SLINT

// Owns a background capture thread that grabs camera frames, runs face
// detection on a throttled cadence, and marshals both the preview image and
// overlay onto the Slint event loop. All camera/IO side-effects live here;
// frame conversion and detection are delegated to RecognizerService.
class PreviewController {
public:
    using FrameCallback = std::function<void(slint::Image, PreviewOverlay)>;

    PreviewController() = default;
    ~PreviewController();
    PreviewController(const PreviewController&) = delete;
    PreviewController& operator=(const PreviewController&) = delete;
    PreviewController(PreviewController&&) = delete;
    PreviewController& operator=(PreviewController&&) = delete;

    // Begin capturing from the given camera at fps frames per second. Each
    // produced frame is handed to callback on the Slint event loop thread.
    // When liveness_enabled is false, predict_liveness skips the anti-spoofing
    // Predict and returns liveness_score=1.0; the overlay status text reflects
    // the disabled state. Callers should gate this on config.liveness_detection.
    void start(su::recognizer::RecognizerService& recognizer,
               int camera_index,
               int fps,
               bool liveness_enabled,
               FrameCallback callback);

    // Signal the capture thread to stop and join it.
    void stop();

    [[nodiscard]] bool is_running() const;

private:
    class Impl;
    // Raw pointer with out-of-line destruction: a unique_ptr member would
    // require Impl to be complete in every TU that sees this header, because
    // the deleter instantiates at the member declaration site. The destructor
    // is defined in the .cpp where Impl is complete.
    Impl* impl_ = nullptr;
};

#endif  // SU_HAS_SLINT

}  // namespace su::app

#include "app/preview_controller.h"

#if SU_HAS_SLINT

#include "recognizer/recognizer_service.h"

#include <atomic>
#include <chrono>
#include <cstdio>
#include <memory>
#include <thread>

namespace su::app {

namespace {

slint::Image preview_frame_to_image(const su::recognizer::PreviewFrame& frame) {
    slint::SharedPixelBuffer<slint::Rgb8Pixel> buffer(
        static_cast<uint32_t>(frame.width),
        static_cast<uint32_t>(frame.height));
    const auto* src = reinterpret_cast<const unsigned char*>(frame.rgba_or_rgb.data());
    auto* dst = buffer.begin();
    const auto pixel_count = static_cast<std::size_t>(frame.width) * frame.height;
    for (std::size_t i = 0; i < pixel_count; ++i) {
        dst[i] = slint::Rgb8Pixel{
            .r = src[i * 3 + 0],
            .g = src[i * 3 + 1],
            .b = src[i * 3 + 2],
        };
    }
    return slint::Image(std::move(buffer));
}

PreviewOverlay overlay_from_result(const su::recognizer::RecognitionResult& result) {
    PreviewOverlay overlay;
    overlay.face_box = result.face_box;
    overlay.liveness_score = result.liveness_score;
    overlay.status_text = result.has_face
        ? "face: liveness " + std::to_string(result.liveness_score)
        : "no face";
    return overlay;
}

}  // namespace

// Single capture+detect thread. SeetaFace's FaceAntiSpoofing is a stateful
// video-stream model that must be fed on consecutive frames to reach a stable
// REAL/SPOOF verdict, so predict_liveness runs on EVERY preview frame (not a
// throttled subset). Feature extraction (the expensive, liveness-irrelevant
// step) is NOT done here; it only runs on explicit enroll/auth. This keeps the
// liveness score accurate while the preview stays on one thread with no
// cross-thread snapshot ownership.
class PreviewController::Impl {
public:
    void start(su::recognizer::RecognizerService& recognizer,
               int camera_index,
               int fps,
               bool liveness_enabled,
               FrameCallback callback) {
        stop();
        if (fps <= 0) {
            fps = 15;
        }
        if (const auto opened = recognizer.open_camera(camera_index); !opened) {
            std::fprintf(stderr, "[preview] open_camera failed\n");
            return;
        }
        recognizer_ = &recognizer;
        running_ = std::make_shared<std::atomic<bool>>(true);

        const auto interval = std::chrono::milliseconds(1000 / fps);
        auto running = running_;

        thread_ = std::thread(
            [running, interval, callback = std::move(callback),
             &recognizer, liveness_enabled]() mutable {
                while (running->load()) {
                    auto frame = recognizer.capture_preview_frame();
                    if (!frame) {
                        slint::invoke_from_event_loop(
                            [callback]() {
                                callback(slint::Image(),
                                         PreviewOverlay{.status_text = "capture failed"});
                            });
                        std::this_thread::sleep_for(interval);
                        continue;
                    }

                    auto image = preview_frame_to_image(*frame);

                    // Run detection + (optionally) liveness on this frame.
                    // predict_liveness feeds anti-spoofing every tick so the
                    // verdict stabilizes; when liveness is disabled in config
                    // the Predict call is skipped entirely and the score is
                    // pinned to 1.0 (passing).
                    auto result = recognizer.predict_liveness(su::recognizer::ImageView{
                        .width = frame->width,
                        .height = frame->height,
                        .channels = 3,
                        .bytes = std::span<const std::byte>(frame->rgba_or_rgb),
                    }, liveness_enabled);

                    PreviewOverlay overlay;
                    if (result && result->has_face) {
                        overlay = overlay_from_result(*result);
                        if (!liveness_enabled) {
                            overlay.status_text = "face: liveness disabled";
                        }
                    } else if (result && !result->has_face) {
                        overlay.status_text = "no face";
                    } else {
                        overlay.status_text = "detect failed";
                    }

                    slint::invoke_from_event_loop(
                        [callback, image = std::move(image),
                         overlay = std::move(overlay)]() mutable {
                            callback(std::move(image), std::move(overlay));
                        });

                    std::this_thread::sleep_for(interval);
                }
            });
    }

    void stop() {
        if (running_) {
            running_->store(false);
        }
        if (thread_.joinable()) {
            thread_.join();
        }
        if (recognizer_ != nullptr) {
            recognizer_->close_camera();
            recognizer_ = nullptr;
        }
    }

    [[nodiscard]] bool is_running() const {
        return running_ && running_->load() && thread_.joinable();
    }

    ~Impl() { stop(); }

private:
    std::thread thread_;
    std::shared_ptr<std::atomic<bool>> running_;
    su::recognizer::RecognizerService* recognizer_ = nullptr;
};

PreviewController::~PreviewController() {
    delete impl_;
}

void PreviewController::start(su::recognizer::RecognizerService& recognizer,
                              int camera_index,
                              int fps,
                              bool liveness_enabled,
                              FrameCallback callback) {
    if (!impl_) {
        impl_ = new Impl();
    }
    impl_->start(recognizer, camera_index, fps, liveness_enabled, std::move(callback));
}

void PreviewController::stop() {
    if (impl_) {
        impl_->stop();
    }
}

bool PreviewController::is_running() const {
    return impl_ != nullptr && impl_->is_running();
}

}  // namespace su::app

#endif  // SU_HAS_SLINT

#include "app/app_controller.h"

#include <iostream>

int main() {
    su::app::AppController controller;
    const auto snapshot = controller.load_initial_snapshot();
    if (!snapshot) {
        std::cerr << "su_app failed to start: " << snapshot.error() << '\n';
        return 1;
    }

    std::cout << snapshot->title << '\n';
    std::cout << "Slint enabled: " << (snapshot->slint_enabled ? "yes" : "no") << '\n';
    std::cout << "Config path: " << snapshot->config_path << '\n';
    std::cout << "Profile store: " << snapshot->profile_store_path << '\n';
    std::cout << "Threshold: " << snapshot->config.recognition_threshold << '\n';
    std::cout << "Selected camera: " << snapshot->config.selected_camera << '\n';
    std::cout << "Preview FPS: " << snapshot->config.preview_fps << '\n';
    std::cout << "Liveness: " << (snapshot->config.liveness_detection ? "yes" : "no") << '\n';
    std::cout << "SeetaFace: " << (snapshot->seetaface_available ? "available" : "unavailable") << '\n';
    std::cout << "Detected cameras: " << snapshot->cameras.size() << '\n';
    for (const auto& camera : snapshot->cameras) {
        std::cout << "  [" << camera.index << "] " << camera.name << '\n';
    }

    const auto demo_auth = controller.evaluate_demo_auth("demo");
    if (!demo_auth) {
        std::cerr << "demo auth failed: " << demo_auth.error() << '\n';
        return 1;
    }
    std::cout << "Demo auth accepted: " << (*demo_auth ? "yes" : "no") << '\n';

    // Read-only: list whatever profiles already exist without enrolling a
    // demo profile into the user's real store as a startup side effect.
    const auto profiles = controller.list_face_profiles();
    if (!profiles) {
        std::cerr << "failed to list face profiles: " << profiles.error() << '\n';
        return 1;
    }
    std::cout << "Face profiles:\n" << *profiles << '\n';
    return 0;
}

